ALTER TABLE public.voucher_items ADD COLUMN lease_at timestamptz;
CREATE FUNCTION public.claim_voucher_item(rid uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i voucher_items; b voucher_batches; BEGIN SELECT vi.* INTO i FROM voucher_items vi JOIN voucher_batches vb ON vb.id=vi.batch_id WHERE vi.router_id=rid AND vb.state='pending' AND (vi.state='pending' OR (vi.state='sent' AND vi.lease_at<now()-interval '2 minutes')) ORDER BY vb.created_at,vi.ordinal FOR UPDATE OF vi SKIP LOCKED LIMIT 1; IF i.id IS NULL THEN RETURN NULL; END IF; UPDATE voucher_items SET state='sent',lease_at=now() WHERE id=i.id; SELECT * INTO b FROM voucher_batches WHERE id=i.batch_id; RETURN jsonb_build_object('item',to_jsonb(i),'batch',to_jsonb(b)); END $$;
REVOKE ALL ON FUNCTION public.claim_voucher_item(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_voucher_item(uuid) TO service_role;
CREATE FUNCTION public.confirm_voucher_item(iid uuid,rid uuid,res text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE bid uuid; BEGIN UPDATE voucher_items SET state=CASE WHEN res='ok' THEN 'confirmed' ELSE 'failed' END,result=res WHERE id=iid AND router_id=rid AND state='sent' RETURNING batch_id INTO bid; IF bid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM voucher_items WHERE batch_id=bid AND state IN ('pending','sent')) THEN UPDATE voucher_batches SET state='complete' WHERE id=bid; END IF; END $$;
REVOKE ALL ON FUNCTION public.confirm_voucher_item(uuid,uuid,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.confirm_voucher_item(uuid,uuid,text) TO service_role;